(function(){
  'use strict';

  const STORE_KEY='vesa.tna360.local.v1';
  const SUPPORTED_LANGUAGES=['en','bn','hi','ta'];
  const COPY={
    en:{app:'VESA TNA 360',tag:'Universal Apparel Time & Action',title:'Plan every order without guessing.',lead:'Create garment-native critical paths, keep original/current/forecast/actual dates separate, and record what is still unknown.',mode:'Local — this browser',modeText:'Domain records and garment templates are active for draft creation. Saving, scheduling engines and reports are completed in later checkpoints.',saved:'Ready',new:'New TNA',newText:'Create a validated draft from quick, full or staged Excel-entry inputs. Required unknowns remain visible.',continue:'Continue Last TNA',continueText:'No saved local TNA exists in this browser yet.',open:'Open Saved TNA',openText:'Local order list appears after G05 storage is implemented.',practice:'Practice Example',practiceText:'Opens a clearly marked training preview. It is not a production order.',copy:'Open Saved Copy',copyText:'Backup validation is planned for G05. Invalid files will be rejected safely.',orders:'All Orders',ordersText:'Shows browser-local orders now; connected multi-company lists require approved backend.',home:'HOME',file:'FILE',edit:'EDIT',view:'VIEW',tools:'TOOLS',help:'HELP',appCentre:'App Centre',menuTitle:'TNA actions',unavailable:'This action is scheduled for a later TNA checkpoint and is not marked complete yet.',cloud:'Connected collaboration is blocked until a server provider, identity, database, storage and notification sender are authorized.',recent:'Recent local work',empty:'No production TNA records are saved in this browser.',next:'Next implementation checkpoint',nextText:'G03 will add calendar and critical-path calculations. G02 only creates validated draft records and templates; it does not invent dates.',privacy:'Business data remains local in this browser until a verified backend is configured.',workspace:'Draft workspace',template:'Template',unknown:'Needs Information',tasks:'Tasks',baseline:'Baseline',validation:'Validation',notSaved:'Draft is not saved yet. G05 adds transaction-safe local saving and backup.',quick:'Quick entry',full:'Full entry',excel:'Excel entry',createDraft:'Create draft',templateLibrary:'Template library'},
    bn:{app:'VESA TNA 360',tag:'Universal Apparel Time & Action',title:'অনুমান ছাড়া প্রতিটি order plan করুন.',lead:'Garment critical path তৈরি করুন, original/current/forecast/actual date আলাদা রাখুন এবং কোন input unknown তা দেখান.',mode:'Local — এই browser',modeText:'এই G01 shell authenticated local work-এর জন্য প্রস্তুত. Domain engine, saving এবং reports পরের checkpoint-এ সম্পন্ন হবে.',saved:'Ready',new:'New TNA',newText:'Quick, full এবং import creation এখানে খুলবে. G02 validated order model এবং templates যোগ করবে.',continue:'Continue Last TNA',continueText:'এই browser-এ saved local TNA নেই.',open:'Open Saved TNA',openText:'G05 storage implement হলে local order list দেখাবে.',practice:'Practice Example',practiceText:'Training preview খুলবে. এটি production order নয়.',copy:'Open Saved Copy',copyText:'Backup validation G05-এ planned. Invalid file safely reject হবে.',orders:'All Orders',ordersText:'এখন browser-local orders দেখাবে; connected multi-company list-এর জন্য approved backend দরকার.',home:'HOME',file:'FILE',edit:'EDIT',view:'VIEW',tools:'TOOLS',help:'HELP',appCentre:'App Centre',menuTitle:'TNA actions',unavailable:'এই action পরের TNA checkpoint-এর জন্য scheduled; complete বলা হচ্ছে না.',cloud:'Server provider, identity, database, storage এবং notification sender authorize না হওয়া পর্যন্ত connected collaboration blocked.',recent:'Recent local work',empty:'এই browser-এ production TNA record save নেই.',next:'Next implementation checkpoint',nextText:'G02 versioned records, universal garment templates এবং New TNA wizard যোগ করবে; PPM/AQL logic বদলাবে না.',privacy:'Verified backend configure না হওয়া পর্যন্ত business data এই browser-এই local থাকবে.'},
    hi:{app:'VESA TNA 360',tag:'Universal Apparel Time & Action',title:'हर order को बिना guess किए plan करें.',lead:'Garment critical path बनाएं, original/current/forecast/actual dates अलग रखें, और unknown inputs साफ दिखाएं.',mode:'Local — इस browser',modeText:'यह G01 shell authenticated local work के लिए तैयार है. Domain engines, saving और reports बाद के checkpoints में पूरे होंगे.',saved:'Ready',new:'New TNA',newText:'Quick, full और import creation यहीं खुलेगा. G02 validated order model और templates जोड़ेगा.',continue:'Continue Last TNA',continueText:'इस browser में saved local TNA अभी नहीं है.',open:'Open Saved TNA',openText:'G05 storage के बाद local order list दिखेगी.',practice:'Practice Example',practiceText:'Training preview खुलेगा. यह production order नहीं है.',copy:'Open Saved Copy',copyText:'Backup validation G05 में planned है. Invalid files safely reject होंगी.',orders:'All Orders',ordersText:'अभी browser-local orders दिखेंगे; connected multi-company lists के लिए approved backend चाहिए.',home:'HOME',file:'FILE',edit:'EDIT',view:'VIEW',tools:'TOOLS',help:'HELP',appCentre:'App Centre',menuTitle:'TNA actions',unavailable:'यह action अगले TNA checkpoint के लिए scheduled है; इसे complete नहीं बताया गया है.',cloud:'Server provider, identity, database, storage और notification sender authorize होने तक connected collaboration blocked है.',recent:'Recent local work',empty:'इस browser में production TNA records saved नहीं हैं.',next:'Next implementation checkpoint',nextText:'G02 versioned records, universal garment templates और New TNA wizard जोड़ेगा; PPM/AQL logic नहीं बदलेगा.',privacy:'Verified backend configure होने तक business data इसी browser में local रहेगा.'},
    ta:{app:'VESA TNA 360',tag:'Universal Apparel Time & Action',title:'Guess இல்லாமல் ஒவ்வொரு order-ஐயும் plan பண்ணுங்கள்.',lead:'Garment critical path உருவாக்கி, original/current/forecast/actual dates-ஐ தனியாக வைத்து, unknown inputs-ஐ தெளிவாக காட்டும்.',mode:'Local — இந்த browser',modeText:'இந்த G01 shell authenticated local work-க்கு ready. Domain engines, saving, reports அடுத்த checkpoints-ல் complete ஆகும்.',saved:'Ready',new:'New TNA',newText:'Quick, full, import creation இங்கே open ஆகும். G02 validated order model மற்றும் templates சேர்க்கும்.',continue:'Continue Last TNA',continueText:'இந்த browser-ல் saved local TNA இன்னும் இல்லை.',open:'Open Saved TNA',openText:'G05 storage வந்த பிறகு local order list தெரியும்.',practice:'Practice Example',practiceText:'Training preview open ஆகும். இது production order இல்லை.',copy:'Open Saved Copy',copyText:'Backup validation G05-ல் planned. Invalid files safely reject ஆகும்.',orders:'All Orders',ordersText:'இப்போது browser-local orders மட்டும்; connected multi-company list-க்கு approved backend வேண்டும்.',home:'HOME',file:'FILE',edit:'EDIT',view:'VIEW',tools:'TOOLS',help:'HELP',appCentre:'App Centre',menuTitle:'TNA actions',unavailable:'இந்த action அடுத்த TNA checkpoint-க்கு scheduled; complete என்று mark செய்யவில்லை.',cloud:'Server provider, identity, database, storage, notification sender authorize ஆகும் வரை connected collaboration blocked.',recent:'Recent local work',empty:'இந்த browser-ல் production TNA records save இல்லை.',next:'Next implementation checkpoint',nextText:'G02 versioned records, universal garment templates, New TNA wizard சேர்க்கும்; PPM/AQL logic மாற்றாது.',privacy:'Verified backend configure ஆகும் வரை business data இந்த browser-லேயே local இருக்கும்.'}
  };

  const MENUS={
    home:['Home','App Centre','All Orders'],
    file:['New TNA','Open Saved TNA','Save Now','Make Another Copy','Download Saved Copy','Open Saved Copy','Import Excel TNA'],
    edit:['Undo','Redo','Edit Order','Add Activity','Edit Dependencies','Revise Target','Review Changes'],
    view:['Dashboard','TNA Planner','Timeline','Critical Path','Due Today','All Orders','Appearance / Language'],
    tools:['Recalculate Dates','Check Missing Information','Production Capacity','Recovery Scenarios','Prepare Report','Download Report','Print Report','Share Report'],
    help:['How to Use','Glossary','Example','About','Data & Backup Help']
  };

  const state={dialog:null,language:'en',currentPlan:null};
  const domain=globalThis.VesaTnaDomain;
  const scheduling=globalThis.VesaTnaScheduling;
  const text=key=>(COPY[state.language]||COPY.en)[key]||COPY.en[key]||key;
  const esc=value=>String(value??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  function readRecords(){try{const raw=JSON.parse(localStorage.getItem(STORE_KEY)||'null');return Array.isArray(raw?.records)?raw.records:[]}catch{return []}}
  function language(){const pref=globalThis.VesaPrefs?.read?.().language||document.documentElement.lang||'en';return SUPPORTED_LANGUAGES.includes(pref)?pref:'en'}
  function actionCard(key,secondary=false,disabled=false){return `<article class="tna-action-card"><h2>${esc(text(key))}</h2><p>${esc(text(key+'Text'))}</p><button type="button" class="${secondary?'secondary':''}" data-action="${esc(key)}" ${disabled?'disabled':''}>${esc(text(key))}</button></article>`}
  function templateOptions(selected='knit'){return Object.values(domain?.TEMPLATE_PROFILES||{}).map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}
  function field(name,label,type='text',value='',required=false){return `<label><span>${esc(label)}${required?' *':''}</span><input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${required?'required':''}></label>`}
  function selectField(name,label,options,value=''){return `<label><span>${esc(label)}</span><select name="${esc(name)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
  function planPanel(plan){if(!plan)return `<div class="tna-panel"><h2>${esc(text('templateLibrary'))}</h2><p>${esc(text('notSaved'))}</p><p>${Object.values(domain?.TEMPLATE_PROFILES||{}).map(t=>esc(t.name)).join(' · ')}</p></div>`;
    const warnings=plan.validation?.warnings||[];const errors=plan.validation?.errors||[];const unknown=plan.unknownFields||[];
    const stageCounts=plan.tasks.reduce((acc,task)=>{acc[task.stageCode]=(acc[task.stageCode]||0)+1;return acc},{});
    return `<div class="tna-panel tna-plan-panel"><div class="tna-plan-head"><div><span class="tna-kicker">${esc(text('workspace'))}</span><h2>${esc(plan.order.styles[0]?.styleNo||'Untitled TNA')} · ${esc(plan.order.buyerName||'Buyer unknown')}</h2><p>${esc(plan.order.factoryName||'Factory unknown')} · ${esc(plan.order.poNumbers[0]||'PO unknown')} · ${esc(plan.order.totalQty??'Qty unknown')} ${esc(plan.order.unit)}</p></div><span class="tna-status-pill">${esc((domain.TEMPLATE_PROFILES[plan.templateId]||{}).name||plan.templateId)}</span></div>
      <div class="tna-metrics"><b>${plan.tasks.length}</b><span>${esc(text('tasks'))}</span><b>${plan.baselineSnapshots.length}</b><span>${esc(text('baseline'))}</span><b>${unknown.length+warnings.length+errors.length}</b><span>${esc(text('validation'))}</span></div>
      <p class="tna-note">${esc(text('notSaved'))}</p>
      ${unknown.length?`<h3>${esc(text('unknown'))}</h3><ul>${unknown.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}
      ${errors.length?`<h3>Errors</h3><ul>${errors.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}
      ${warnings.length?`<h3>Warnings</h3><ul>${warnings.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}
      ${schedulePanel(plan)}
      <h3>Stages</h3><div class="tna-stage-chips">${Object.entries(stageCounts).map(([stage,count])=>`<span>${esc(stage)} · ${count}</span>`).join('')}</div>
      <h3>First activities</h3><div class="tna-task-table" role="table" aria-label="Draft TNA activities">${plan.tasks.slice(0,12).map(task=>`<div role="row"><span>${esc(task.templateRef)}</span><span>${esc(task.title)}</span><span>${esc(task.ownerParty)}</span><span>${esc(task.status)}</span></div>`).join('')}</div></div>`}
  function render(){state.language=language();const records=readRecords();const root=document.getElementById('tnaMain');root.innerHTML=`
    <nav class="tna-commandbar" aria-label="TNA workspace menu">
      ${['home','file','edit','view','tools','help'].map(k=>`<button type="button" data-menu="${k}">${esc(text(k))}</button>`).join('')}
      <span class="spacer"></span><a href="/apps/">${esc(text('appCentre'))}</a><span class="tna-save-state">${esc(text('saved'))}</span>
    </nav>
    <section class="tna-hero">
      <div class="tna-hero-card"><span class="tna-kicker">${esc(text('tag'))}</span><h1>${esc(text('title'))}</h1><p class="tna-lead">${esc(text('lead'))}</p><p class="tna-note">${esc(text('privacy'))}</p></div>
      <aside class="tna-status-card"><span class="tna-status-pill">${esc(text('mode'))}</span><p class="tna-muted">${esc(text('modeText'))}</p><p class="tna-muted">${esc(text('cloud'))}</p></aside>
    </section>
    <section class="tna-grid" aria-label="TNA home actions">
      ${actionCard('new')}${actionCard('continue',true,records.length===0)}${actionCard('open',true)}${actionCard('practice',true)}${actionCard('copy',true)}${actionCard('orders',true)}
    </section>
    <section class="tna-two">
      <div class="tna-panel"><h2>${esc(text('recent'))}</h2><div class="tna-list">${records.length?records.map(r=>`<article><b>${esc(r.style||'Untitled TNA')}</b><p>${esc(r.buyer||'Buyer unknown')} · ${esc(r.po||'PO unknown')}</p></article>`).join(''):`<article>${esc(text('empty'))}</article>`}</div></div>
      ${planPanel(state.currentPlan)}
    </section>
    <p class="tna-footer-note">VESA Enterprise Inc. · Powered by EGENVA · ${esc(text('mode'))}</p>
    <dialog class="tna-dialog" id="tnaDialog"><div class="tna-dialog-head"><h2 id="tnaDialogTitle"></h2><button type="button" aria-label="Close">×</button></div><div class="tna-dialog-body" id="tnaDialogBody"></div></dialog>`;
    state.dialog=document.getElementById('tnaDialog');state.dialog.querySelector('button').onclick=()=>state.dialog.close();
    root.querySelectorAll('[data-menu]').forEach(btn=>btn.onclick=()=>openMenu(btn.dataset.menu));
    root.querySelectorAll('[data-action]').forEach(btn=>btn.onclick=()=>openAction(btn.dataset.action));
  }
  function openDialog(title,body){document.getElementById('tnaDialogTitle').textContent=title;document.getElementById('tnaDialogBody').innerHTML=body;if(!state.dialog.open)state.dialog.showModal();}
  function openMenu(name){const items=MENUS[name]||[];openDialog(text('menuTitle')+' · '+text(name),`<div class="menu-grid">${items.map(item=>`<button class="tna-btn secondary" type="button" data-menu-action="${esc(item)}">${esc(item)}</button>`).join('')}</div><p class="tna-note">${esc(text('unavailable'))}</p>`);document.querySelectorAll('[data-menu-action]').forEach(btn=>btn.onclick=()=>btn.textContent==='Add Activity'?openCustomTask():openDialog(btn.textContent,`<p>${esc(text('unavailable'))}</p>`));}
  function openAction(action){if(action==='new')return openWizard('quick');if(action==='practice')return createPractice();openDialog(text(action)||action,`<p>${esc(text(action+'Text')||text('unavailable'))}</p><p class="tna-note">${esc(text('unavailable'))}</p>`);}
  function openWizard(mode){const isFull=mode==='full';const body=`<form class="tna-wizard" id="tnaWizard">
      <div class="tna-tabs"><button type="button" data-wizard-tab="quick" class="${mode==='quick'?'active':''}">${esc(text('quick'))}</button><button type="button" data-wizard-tab="full" class="${mode==='full'?'active':''}">${esc(text('full'))}</button><button type="button" data-wizard-tab="excel" class="${mode==='excel'?'active':''}">${esc(text('excel'))}</button></div>
      ${mode==='excel'?excelEntry():standardEntry(isFull)}
      <p class="tna-note">${esc(mode==='excel'?'Excel imports are staged here as reviewed text mapping only. Real workbook parsing, formula safety and round-trip export are G05.':'Missing buyer, factory, style, PO, quantity or ex-factory date will stay marked as Needs Information. No dates are guessed.')}</p>
      <button class="tna-btn" type="submit">${esc(text('createDraft'))}</button></form>`;
    openDialog(text('new'),body);
    document.querySelectorAll('[data-wizard-tab]').forEach(btn=>btn.onclick=()=>openWizard(btn.dataset.wizardTab));
    document.getElementById('tnaWizard').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries());data.processFlags=Array.from(event.currentTarget.querySelectorAll('[name="processFlags"]:checked')).map(input=>input.value);state.currentPlan=domain.createPlan(data,{ownerUserId:globalThis.VesaAuth?.userKey?.()||'local-browser-user'});state.dialog.close();render();};
  }
  function standardEntry(isFull){return `<div class="tna-form-grid">
      ${selectField('templateId','Product template',Object.values(domain.TEMPLATE_PROFILES).map(t=>[t.id,t.name]),'knit')}
      ${field('buyerName','Buyer','text','',true)}${field('factoryName','Factory','text','',true)}${field('styleNo','Style','text','',true)}${field('poNumber','PO / order reference','text','',true)}${field('totalQty','Total quantity','number','',true)}${field('buyerRequiredExFactory','Buyer required ex-factory','date','',true)}
      ${isFull?`${field('orderConfirmedOn','Explicit start / order confirmed date','date')}${field('poReceivedOn','PO received date','date')}${field('brand','Brand')}${field('destinationMarket','Destination / market')}${field('fabricSpec','Fabric specification')}${selectField('fabricRoute','Fabric route',[['unknown','Unknown'],['local-ready','Local ready fabric'],['local-manufactured','Local manufactured'],['imported-finished','Imported finished'],['imported-greige','Imported greige / yarn']], 'unknown')}${field('techPackRevision','Tech pack revision')}${field('composition','Composition')}${field('sizeRange','Size range')}${field('incoterm','Incoterm')}${field('shipmentMethod','Shipment method')}`:''}
    </div><fieldset class="tna-checks"><legend>Conditional processes</legend>${[['print','Print'],['embroidery','Embroidery'],['aop','AOP / strike-off'],['wash','Wash / garment dye'],['performance','Performance test']].map(([v,l])=>`<label><input type="checkbox" name="processFlags" value="${esc(v)}"> ${esc(l)}</label>`).join('')}</fieldset>`}
  function excelEntry(){return `<div class="tna-form-grid">${field('buyerName','Buyer from sheet')}${field('factoryName','Factory from sheet')}${field('styleNo','Style from sheet')}${field('poNumber','PO from sheet')}${field('totalQty','Quantity from sheet','number')}${field('buyerRequiredExFactory','Ex-factory from sheet','date')}${selectField('templateId','Template mapping',Object.values(domain.TEMPLATE_PROFILES).map(t=>[t.id,t.name]),'custom')}</div><label class="tna-wide"><span>Reviewed import notes / unmatched columns</span><textarea name="commercialNotes" rows="5" placeholder="Paste header mapping notes here. This does not overwrite any existing TNA."></textarea></label>`}
  function createPractice(){state.currentPlan=domain.createPlan({templateId:'denim',buyerName:'Training Buyer',factoryName:'Training Factory',styleNo:'DENIM-PRACTICE',poNumber:'TRAINING-PO',totalQty:1200,buyerRequiredExFactory:'2026-11-30',processFlags:['wash'],fabricRoute:'local-manufactured'},{mode:'practice',ownerUserId:'practice'});render();}
  function schedulePanel(plan){if(!scheduling)return '';
    const start=plan.commitments.orderConfirmedOn||plan.commitments.poReceivedOn;
    const required=plan.commitments.buyerRequiredExFactory;
    if(!start||!required)return `<h3>Schedule</h3><p class="tna-note">Schedule unavailable: enter an explicit start date and buyer required ex-factory date. No date is invented from PO or today.</p>`;
    const result=scheduling.schedule(plan.tasks,plan.edges,{calendar:plan.calendars[0],startDate:start,requiredDate:required,asOfDate:start});
    if(result.validity!=='valid')return `<h3>Schedule</h3><p class="tna-note">Schedule unavailable: ${esc([...result.missingInputs,...result.errors].join(', '))}</p>`;
    return `<h3>Schedule</h3><div class="tna-stage-chips"><span>Forecast · ${esc(result.project.forecastDate)}</span><span>${result.project.workingDaysEarlyOrLate>0?'Late':'Float'} · ${esc(result.project.workingDaysEarlyOrLate)} working day(s)</span><span>Critical chains · ${esc(result.project.criticalPaths.length)}</span></div><p class="tna-note">Calculated forecast only. Baseline/current/actual dates are not overwritten.</p>`;
  }
  function openCustomTask(){if(!state.currentPlan)return openDialog('Add Activity',`<p>Create a draft TNA first, then add custom checkpoints to that draft.</p>`);
    openDialog('Add Activity',`<form class="tna-wizard" id="tnaCustomTask"><div class="tna-form-grid">${field('title','Activity title','text','',true)}${selectField('stageCode','Stage',Object.entries(domain.STAGE_LABELS).map(([k,v])=>[k,`${k} · ${v}`]),'O')}${field('ownerParty','Owner party','text','merchant')}${field('durationUnits','Duration units','number','0')}</div><p class="tna-note">Custom activities are added as optional draft checkpoints with audit history. They do not change baseline snapshots silently.</p><button class="tna-btn" type="submit">Add Activity</button></form>`);
    document.getElementById('tnaCustomTask').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries());const result=domain.addCustomTask(state.currentPlan,data,{actorId:globalThis.VesaAuth?.userKey?.()||'local-browser-user'});if(result.ok){state.currentPlan=result.plan;state.dialog.close();render();}else openDialog('Add Activity',`<p>${esc(result.error||(result.errors||[]).join(', '))}</p>`);};
  }
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.dialog?.open)state.dialog.close();});
  window.addEventListener('vesa-preferences-change',render);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render);else render();
})();
